const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(x,n=1)=>Number.isFinite(x)?x.toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}):'—',pct=(x,n=1)=>Number.isFinite(x)?fmt(x*100,n)+'%':'—',signed=x=>(x>0?'+':'')+fmt(x),count=x=>fmt(x,0);
const PAGES=[['overview','01','Start here'],['matchup','02','Matchups'],['series','03','Series simulator'],['players','04','Players'],['lineups','05','Lineups'],['shots','06','Shot charts'],['strategy','07','Scouting notes'],['methodology','08','About the data']];
const NAMES={ATL:'Atlanta Hawks',BOS:'Boston Celtics',BKN:'Brooklyn Nets',CHA:'Charlotte Hornets',CHI:'Chicago Bulls',CLE:'Cleveland Cavaliers',DAL:'Dallas Mavericks',DEN:'Denver Nuggets',DET:'Detroit Pistons',GSW:'Golden State Warriors',HOU:'Houston Rockets',IND:'Indiana Pacers',LAC:'LA Clippers',LAL:'Los Angeles Lakers',MEM:'Memphis Grizzlies',MIA:'Miami Heat',MIL:'Milwaukee Bucks',MIN:'Minnesota Timberwolves',NOP:'New Orleans Pelicans',NYK:'New York Knicks',OKC:'Oklahoma City Thunder',ORL:'Orlando Magic',PHI:'Philadelphia 76ers',PHX:'Phoenix Suns',POR:'Portland Trail Blazers',SAC:'Sacramento Kings',SAS:'San Antonio Spurs',TOR:'Toronto Raptors',UTA:'Utah Jazz',WAS:'Washington Wizards'};
let D,S,route='overview',state={seriesA:'BOS',seriesB:'OKC',seriesCourt:'A',seriesWinsA:0,seriesWinsB:0,seriesAdjustment:0,similarRole:false,home:'BOS',away:'OKC',rest:0,player:'Jayson Tatum',compare:'Shai Gilgeous-Alexander',season:'2024-25',team:'BOS',shotTeam:'BOS',shotPlayer:'all',zone:'all',shotType:'all',minPoss:100,priorStrength:200,selected:[]},shotCache={},renderID=0;
const team=t=>D.teams.find(x=>x.team===t&&x.season==='2024-25');
const teamOptions=v=>Object.keys(NAMES).sort().map(t=>`<option value="${t}" ${t===v?'selected':''}>${NAMES[t]}</option>`).join('');
const PAGE_HELP={
 matchup:['Pick a home and away team. The large percentages are the model’s estimated chance of each team winning.','Use the team statistics below to look for differences, then open a series or shooting chart.','Net rating means points scored minus points allowed per 100 possessions. The displayed model range is not a guarantee.'],
 players:['Choose a season, then search for a player or select one from the list.','Pick a second player to compare. Similar-player suggestions describe statistical profiles, not equal talent.','A percentile shows where a player sits among the comparison group; 80 means above about 80% of that group.'],
 lineups:['Choose a team and a minimum sample size. Start with 100 possessions.','Use A and B to compare two observed lineups. The alternatives table finds units sharing four players.','Shrunk net rating pulls small samples toward the team’s available-lineup average. It does not measure the effect of replacing a player.'],
 shots:['Choose a team, then narrow the chart to a player, zone or shot value.','Orange dots are made shots; blue dots are misses. Check the table for exact totals.','PPS means points per shot attempt. The expected value describes shot quality from recorded location and game context, not every factor affecting a shot.'],
 strategy:['Choose your matchup, then read the questions below.','Open a note to see the supporting numbers and what would need to be tested.','These are scouting hypotheses, not measured effects of a coaching decision.'],
 methodology:['Start with the data sources and season splits.','Validation results compare the model with simple baselines. Lower log loss means better probability predictions.','Read the limitations before interpreting a result as a forecast or a causal claim.']};
function pageHelp(){const steps=PAGE_HELP[route];return steps?`<details class="page-help"><summary>Quick guide to this page</summary><ol>${steps.map(step=>`<li>${step}</li>`).join('')}</ol></details>`:''}
const head=(ey,title,sub,tag='2024–25 · REGULAR SEASON')=>`<div class="page-head"><div><div class="eyebrow">${ey}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><span class="tag">${tag}</span></div>${pageHelp()}`;
const kpi=(label,value,detail='',cls='')=>`<div class="kpi"><div class="label">${label}</div><div class="value ${cls}">${value}</div><div class="detail">${detail}</div></div>`;
const panel=(title,body,sub='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2><small>${sub}</small></div>${body}</section>`;
function court(markers=false){return `<svg viewBox="0 0 500 470" role="img" aria-label="NBA half court. Basket at bottom; coordinates in tenths of feet."><rect x="1" y="1" width="498" height="468" rx="2" fill="#e8d3b6" stroke="#a18a70"/><g fill="none" stroke="#a18a70" stroke-width="1.2"><path d="M30 470V330 M470 470V330 M30 330 A237.5 237.5 0 0 1 470 330"/><rect x="170" y="280" width="160" height="190"/><rect x="190" y="280" width="120" height="190"/><circle cx="250" cy="280" r="60"/><path d="M210 417.5 A40 40 0 0 1 290 417.5"/><path d="M220 430H280"/><circle cx="250" cy="417.5" r="7.5" stroke="#a64327"/><path d="M190 1 A60 60 0 0 0 310 1"/></g>${markers?'<g fill="#a64327" opacity=".6"><circle cx="30" cy="365" r="8"/><circle cx="365" cy="200" r="6"/><circle cx="255" cy="370" r="9"/><circle cx="120" cy="220" r="5"/><circle cx="385" cy="300" r="4"/></g>':''}</svg>`}
function spark(values,color='#a64327',label='Trend'){const w=540,h=130,lo=Math.min(...values,0)-3,hi=Math.max(...values,0)+3,points=values.map((v,i)=>`${15+i*(w-30)/Math.max(1,values.length-1)},${h-12-(v-lo)/(hi-lo)*(h-25)}`).join(' '),zero=h-12-(0-lo)/(hi-lo)*(h-25);return `<svg class="spark" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><line x1="15" x2="525" y1="${zero}" y2="${zero}" stroke="#c9bbaa" stroke-dasharray="3 4"/><polyline points="${points}" stroke="${color}" fill="none" stroke-width="2.3" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${15+i*(w-30)/Math.max(1,values.length-1)}" cy="${h-12-(v-lo)/(hi-lo)*(h-25)}" r="3" fill="${color}"><title>${esc(label)} · ${i+1}: ${fmt(v)}</title></circle>`).join('')}</svg>`}
function bar(label,value,display,color='var(--green)'){return `<div class="stat-bar"><header><span>${label}</span><span>${display}</span></header><div class="bar-track"><span style="width:${Math.max(0,Math.min(100,value))}%;background:${color}"></span></div></div>`}
function matchupFilters(){return `<div class="filters"><label>Home team<select id="home">${teamOptions(state.home)}</select></label><div class="muted small" style="padding-bottom:10px">vs</div><label>Away team<select id="away">${teamOptions(state.away)}</select></label><div class="filter-spacer"></div>${D.model.features.includes('rest_gap')?`<label>Home rest advantage · <span id="restValue">${state.rest}</span> days<input id="rest" type="range" min="-6" max="6" value="${state.rest}" aria-label="Home rest advantage in days"></label>`:'<span class="tiny muted">ELO MODEL · REST NOT INCLUDED</span>'}<button id="swap" class="btn" aria-label="Swap home and away teams">⇄ Swap</button></div>`}
function wireMatchup(){['home','away'].forEach(id=>$('#'+id).onchange=e=>{state[id]=e.target.value;render()});if($('#rest')){$('#rest').onchange=e=>{state.rest=+e.target.value;render()};$('#rest').oninput=e=>$('#restValue').textContent=e.target.value;}$('#swap').onclick=()=>{[state.home,state.away]=[state.away,state.home];state.rest=-state.rest;render()}}
function analysisLinks(){return `<div class="row analysis-links"><a class="btn" id="startSeries" href="#series">Start ${state.home}–${state.away} series →</a><a class="btn" id="homeShots" href="#shots">Inspect ${state.home} shooting →</a><a class="btn" id="awayShots" href="#shots">Inspect ${state.away} shooting →</a></div>`}
function wireAnalysisLinks(){
 if($('#startSeries'))$('#startSeries').onclick=()=>Object.assign(state,{seriesA:state.home,seriesB:state.away,seriesCourt:'A',seriesWinsA:0,seriesWinsB:0,seriesAdjustment:0});
 for(const [id,key] of [['homeShots','home'],['awayShots','away']])if($('#'+id))$('#'+id).onclick=()=>Object.assign(state,{shotTeam:state[key],shotPlayer:'all',zone:'all',shotType:'all'});
}
function match(home=state.home,away=state.away,rest=state.rest){const a=team(home),b=team(away),x=features(a.profile,b.profile,rest),r=probability(D.model,x),bs=D.bootstrap.map(m=>probability(m,x).p);return {a,b,x,...r,low:quantile(bs,.1),high:quantile(bs,.9)}}
function predictionCard(m){return `<div class="row between"><div class="row"><span class="team-badge">${m.a.team}</span><div><h3>${NAMES[m.a.team]}</h3><span class="tiny muted">HOME · ${m.a.wins}–${m.a.games-m.a.wins}</span></div></div><span class="match-vs">VS</span><span class="team-badge blue">${m.b.team}</span></div><div class="prob-display"><div><div class="prob-num green">${fmt(m.p*100,1)}<small>%</small></div><span class="tiny muted">HOME WIN ESTIMATE</span></div><div style="text-align:right"><div class="prob-num cyan">${fmt((1-m.p)*100,1)}<small>%</small></div><span class="tiny muted">${NAMES[m.b.team].toUpperCase()}</span></div></div><div class="prob-bar"><i style="width:${m.p*100}%"></i></div><div class="row between tiny muted"><span>Model range: ${pct(m.low,0)}–${pct(m.high,0)}</span><span>80% bootstrap interval</span></div><p class="footnote">Hypothetical matchup using season-end opponent-adjusted Elo ratings. The efficiency charts separately describe the final 10 games. The range measures model instability, not all basketball uncertainty.</p>`}
function overview(){const distinct=state.home!==state.away;return `${head('COURTVISION','Start with two teams.','A matchup, a playoff series, or a closer look at the players. Choose what you want to understand.')}<section class="matchup-start" aria-labelledby="start-title"><div class="start-intro"><span class="eyebrow">01 / CHOOSE YOUR MATCHUP</span><h2 id="start-title">Who’s on the floor?</h2><p>Use the 2024–25 season to explore how two teams compare.</p><div class="start-pickers"><label>Home team<select id="startHome">${teamOptions(state.home)}</select></label><span class="start-versus" aria-hidden="true">vs</span><label>Away team<select id="startAway">${teamOptions(state.away)}</select></label></div>${distinct?'':'<p class="start-error" role="status">Choose two different teams to continue.</p>'}<button class="btn primary" id="openMatchup" ${distinct?'':'disabled'}>Compare these teams <span aria-hidden="true">→</span></button><p class="start-caption">Historical comparison · not a live game forecast</p></div><div class="start-followups"><span class="eyebrow">02 / TAKE IT FURTHER</span><button class="start-option" id="openSeries" ${distinct?'':'disabled'}><span class="option-number">7</span><span><strong>Play a seven-game series</strong><small>Change the score and home court. See how the odds shift.</small></span><span aria-hidden="true">↗</span></button><button class="start-option" id="openNotes" ${distinct?'':'disabled'}><span class="option-number">↔</span><span><strong>Find the matchup questions</strong><small>Explore shooting, turnovers and rebounding for this pair.</small></span><span aria-hidden="true">↗</span></button><a class="start-proof" href="#methodology">Where do these numbers come from? ↗</a></div></section><section class="section" aria-labelledby="browse-title"><div class="panel-head"><h2 id="browse-title">Or, follow your own question.</h2><small>THREE WAYS IN</small></div><div class="grid3">${[['01','Who fits this role?','Compare players and find similar statistical profiles.','players','Explore players'],['02','Which five play well?','Compare observed lineups and one-player differences.','lineups','Explore lineups'],['03','Where do the points come from?','See shot locations, efficiency and scoring patterns.','shots','Explore shots']].map(([n,t,sub,href,label])=>`<a class="panel flow-card" href="#${href}"><span class="flow-number">${n}</span><h3>${t}</h3><p>${sub}</p><span class="flow-action">${label} <span aria-hidden="true">→</span></span></a>`).join('')}</div></section><aside class="data-strip"><span><strong>30 teams</strong> · 2024–25 snapshot</span><span><strong>${count(S.shot_count)}</strong> recorded shots</span><span><strong>${count(S.lineup_count)}</strong> observed lineups</span><a href="#methodology">Sources & limits →</a></aside>`}
function wireOverview(){
 for(const [id,key] of [['startHome','home'],['startAway','away']])$('#'+id).onchange=e=>{state[key]=e.target.value;render()};
 $('#openMatchup').onclick=()=>{if(state.home!==state.away)location.hash='matchup'};
 $('#openSeries').onclick=()=>{if(state.home===state.away)return;Object.assign(state,{seriesA:state.home,seriesB:state.away,seriesCourt:'A',seriesWinsA:0,seriesWinsB:0,seriesAdjustment:0});location.hash='series'};
 $('#openNotes').onclick=()=>{if(state.home!==state.away)location.hash='strategy'};
}

const factorNames={net_rating_gap:'Recent net rating',efg_gap:'Effective field goal %',turnover_gap:'Turnover rate',rebound_gap:'Offensive rebound share',rest_gap:'Rest advantage',vulnerability_gap:'Experimental vulnerability',elo_gap:'Opponent-adjusted Elo strength'};
function matchup(){if(state.home===state.away)return head('TEAM COMPARISON','Choose a matchup','Choose two different teams to compare.')+matchupFilters()+'<div class="empty">Select a different opponent to run the model.</div>';const m=match(),a=m.a.profile,b=m.b.profile;return `${head('TEAM COMPARISON','How do they match up?','Compare recent strengths, inspect model drivers, and understand what the evidence can—and cannot—tell us.')}${matchupFilters()}${analysisLinks()}<div class="grid2 equal">${panel('Matchup probability',predictionCard(m),'MODEL ESTIMATE')}${panel('The statistical matchup', [['off','Offensive rating',false],['def','Defensive rating',false],['efg','Effective FG%',true],['tov','Turnover rate',true],['orb','Offensive rebound share',true],['poss','Possessions / game',false]].map(([k,l,isPct])=>`<div class="metric-row"><span class="green">${isPct?pct(a[k]):fmt(a[k])}</span><div class="mid">${l}<div class="duel-bars"><div class="duel-half"><i style="width:${100*a[k]/Math.max(a[k],b[k])}%"></i></div><div class="duel-half"><b style="width:${100*b[k]/Math.max(a[k],b[k])}%"></b></div></div></div><span class="cyan">${isPct?pct(b[k]):fmt(b[k])}</span></div>`).join(''),'LAST 10 GAMES')}</div><div class="grid2 section">${panel('What moves the estimate',D.model.features.map((f,i)=>bar(factorNames[f],Math.abs(m.contributions[i])*55,`${signed(m.contributions[i])} log-odds`,m.contributions[i]>=0?'var(--green)':'var(--cyan)')).join('')+`<p class="footnote">Positive contributions favor the home team relative to the training mean. Intercept: ${fmt(D.model.intercept,3)}. These are model associations, not causal effects.</p>`)}${panel('Recent performance',spark(m.a.trend.map(t=>t.net),'#a64327',m.a.team+' net rating')+spark(m.b.trend.map(t=>t.net),'#285e78',m.b.team+' net rating')+`<div class="chart-legend"><span class="green">● ${m.a.team}</span><span class="cyan">● ${m.b.team}</span><span>Last 20 games · separate y-scales</span></div>`,'GAME NET RATING')}</div><div class="note">Historical research scenario as of ${m.a.last_date}. No injuries, roster changes, travel, or upcoming schedule information are included. Home/away season records: ${m.a.team} home ${m.a.home_wins}/${m.a.home_games} wins; ${m.b.team} away ${m.b.away_wins}/${m.b.away_games}.</div>`}
const playerMetrics=[['ts_calc','True shooting',true],['points_36','Scoring / 36',false],['assists_36','Assists / 36',false],['rebounds_36','Rebounds / 36',false],['three_point_attempts_36','3PA / 36',false]];
function playerOptions(name){return D.players.filter(p=>p.season===state.season&&p.minutes>=100).sort((a,b)=>a.player_name.localeCompare(b.player_name)).map(p=>`<option ${p.player_name===name?'selected':''} value="${esc(p.player_name)}">${esc(p.player_name)} · ${p.team}</option>`).join('')}
function peers(p){return D.players.filter(x=>x.season===state.season&&x.minutes>=500&&x.role===p.role)}
function radar(p,q){const ps=peers(p),qs=peers(q),cx=180,cy=125,R=80;const pt=(i,r)=>[cx+Math.cos(-Math.PI/2+i*2*Math.PI/5)*r,cy+Math.sin(-Math.PI/2+i*2*Math.PI/5)*r];const poly=(v)=>v.map((x,i)=>pt(i,x*R/100).join(',')).join(' ');return `<svg class="radar" viewBox="0 0 360 245" role="img" aria-label="Role-peer percentiles for ${esc(p.player_name)} and ${esc(q.player_name)}"><g fill="none" stroke="#c9bbaa">${[25,50,75,100].map(v=>`<polygon points="${poly(Array(5).fill(v))}"/>`).join('')}${playerMetrics.map((_,i)=>{let [x,y]=pt(i,R);return `<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}"/>`}).join('')}</g><polygon points="${poly(playerMetrics.map(([k])=>percentile(p[k],ps.map(x=>x[k]))??0))}" fill="#a6432722" stroke="#a64327" stroke-width="2"/><polygon points="${poly(playerMetrics.map(([k])=>percentile(q[k],qs.map(x=>x[k]))??0))}" fill="#285e7815" stroke="#285e78" stroke-width="2"/>${playerMetrics.map(([k,l],i)=>{let [x,y]=pt(i,R+23);return `<text x="${x}" y="${y}" text-anchor="middle" fill="#635b54" font-size="9">${l}</text>`}).join('')}</svg>`}
function players(){const available=D.players.filter(p=>p.season===state.season&&p.minutes>=100);let p=available.find(x=>x.player_name===state.player)||available[0],q=available.find(x=>x.player_name===state.compare)||available[1];state.player=p.player_name;state.compare=q.player_name;const peer=peers(p),ranks=playerMetrics.map(([k,l])=>({key:k,label:l,v:percentile(p[k],peer.map(x=>x[k]))})).sort((a,b)=>b.v-a.v),history=D.players.filter(x=>x.player_name===p.player_name).sort((a,b)=>a.season.localeCompare(b.season)),ci=wilson(p.three_point_makes,p.three_point_attempts);return `${head('PLAYER PROFILES','Find your player.','Compare efficiency and production with relevant position peers. Explore season-level trends without confusing volume with impact.',state.season+' · PLAYER PROFILES')}<div class="filters"><label>Season<select id="season">${['2022-23','2023-24','2024-25'].map(s=>`<option ${s===state.season?'selected':''}>${s}</option>`).join('')}</select></label><label>Search players<input id="search" type="search" placeholder="Search by name…" aria-label="Search players"></label><span class="tiny muted" id="searchCount" role="status" aria-live="polite">${available.length} players with ≥100 minutes</span></div><div id="searchResults" class="search-results" aria-label="Player search results"></div><div class="player-selects"><label>Primary player<select id="player">${playerOptions(state.player)}</select></label><label>Comparison player<select id="compare">${playerOptions(state.compare)}</select></label></div><div class="grid4 section">${kpi('True shooting',pct(p.ts_calc),'Calculated from points, FGA and FTA','green')}${kpi('Usage rate',pct(p.usage_rate),'Source-provided possession usage')}${kpi('Points per 36',fmt(p.points_36),count(p.minutes)+' minutes played')}${kpi('3-point accuracy',pct(p.three_point_pct),count(p.three_point_attempts)+' attempts · 95% interval '+pct(ci[0],0)+'–'+pct(ci[1],0))}</div><div class="grid2 section">${panel('Player intelligence report',`<div class="player-title">${esc(p.player_name)}</div><p class="player-meta">${p.team} · ${esc(p.position||'Position unavailable')} · ${p.games_played} games · ${state.season}</p><div class="report"><div class="report-item"><h3><span class="number">01</span>Strongest relative dimension: ${ranks[0].label}</h3><p>${fmt(ranks[0].v,0)}th percentile among ${peer.length} ${esc(p.role)}-group players with ≥500 minutes. This describes a statistical profile, not total player value.</p></div><div class="report-item"><h3><span class="number">02</span>Lower relative dimension: ${ranks.at(-1).label}</h3><p>${fmt(ranks.at(-1).v,0)}th percentile. Role and team responsibilities may explain the gap; inspect before treating it as a weakness.</p></div><div class="report-item"><h3><span class="number">03</span>Tactical question to investigate</h3><p>${p.three_rate>.4?'Test whether lineups can use this player’s high three-point attempt share to create spacing. Attempts alone do not prove defensive gravity.':'Explore roles that emphasize this player’s strongest production dimension. Validate with film and lineup context before making a rotation change.'}</p></div><div class="report-item"><h3><span class="number">04</span>Evidence boundary</h3><p>Season aggregates cannot isolate individual defensive impact. Source team labels may represent a traded player’s final team while totals span teams. ${p.minutes<500?'Small sample: this player has fewer than 500 minutes.':''}</p></div></div>`)}${panel('Role-relative profile',radar(p,q)+`<div class="chart-legend"><span class="green">● ${esc(p.player_name)}</span><span class="cyan">● ${esc(q.player_name)}</span></div><p class="footnote">Each player is compared with their own first-listed position group (G/F/C), minimum 500 minutes. Larger values indicate more production, not always better play. Missing positions in older seasons form an unknown group.</p>`)}</div><div class="grid2 equal section">${panel('Side-by-side comparison',`<div class="table-wrap"><table><thead><tr><th>METRIC</th><th>${esc(p.player_name)}</th><th>${esc(q.player_name)}</th></tr></thead><tbody>${[...playerMetrics,['turnovers_36','Turnovers / 36',false],['usage_rate','Usage',true],['three_rate','3PA / FGA',true]].map(([k,l,isPct])=>`<tr><td>${l}</td><td class="green">${isPct?pct(p[k]):fmt(p[k])}</td><td class="cyan">${isPct?pct(q[k]):fmt(q[k])}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Season trajectory',spark(history.map(x=>x.ts_calc*100),'#a64327','True shooting %')+`<div class="chart-labels">${history.map(x=>`<span>${x.season}<br>${pct(x.ts_calc)}</span>`).join('')}</div><p class="footnote">True shooting by season. This is a season-level trend, not a game log. Three-point shrinkage estimate: ${pct(p.three_smoothed)} using a declared 50-attempt, 36% reference prior.</p>`)}</div>${similarityPanel(p)}`}

const similarityKeys=['ts_calc','points_36','assists_36','rebounds_36','three_point_attempts_36','turnovers_36','usage_rate','three_rate'];
const similarityLabels={ts_calc:'True shooting',points_36:'Points / 36',assists_36:'Assists / 36',rebounds_36:'Rebounds / 36',three_point_attempts_36:'3PA / 36',turnovers_36:'Turnovers / 36',usage_rate:'Usage',three_rate:'3PA share'};
function similarityPanel(p){
 const pool=D.players.filter(x=>x.season===state.season&&x.minutes>=500&&(!state.similarRole||x.role===p.role));
 const nearest=similarPlayers(p,pool,similarityKeys);
 return `<section class="panel section"><div class="panel-head"><div><div class="eyebrow">PROFILE DISCOVERY</div><h2>Who plays a statistically similar role?</h2></div><label class="similar-filter"><input id="similarRole" type="checkbox" ${state.similarRole?'checked':''}> Same position group only</label></div><p class="footnote">Nearest profiles to ${esc(p.player_name)} across eight efficiency, usage and per-36 dimensions. Reference pool: ${pool.length} players with ≥500 minutes in ${state.season}. Lower standardized distance means closer production profiles, not equal talent, defensive impact or team fit.</p><div class="table-wrap"><table><thead><tr><th>PLAYER</th><th>DISTANCE ↓</th><th>LARGEST PROFILE DIFFERENCE</th><th></th></tr></thead><tbody>${nearest.map(({player,distance,differences})=>{const gap=[...differences].sort((a,b)=>Math.abs(b.z)-Math.abs(a.z))[0];return `<tr><td><strong>${esc(player.player_name)}</strong><br><span class="tiny muted">${esc(player.team)} · ${esc(player.role)} · ${count(player.minutes)} min</span></td><td>${fmt(distance,2)} SD</td><td>${similarityLabels[gap.key]}<br><span class="tiny muted">${signed(gap.z)} reference SD vs ${esc(p.player_name)}</span></td><td><button class="chip" data-similar="${esc(player.player_name)}">Compare →</button></td></tr>`;}).join('')||'<tr><td colspan="4">Not enough complete profiles to calculate similarity for this cohort.</td></tr>'}</tbody></table></div><details class="similar-method"><summary>How the distance works</summary><p class="footnote">For each dimension, divide the difference by its standard deviation in the selected complete-data reference pool. Take the square root of the mean squared standardized differences. Each dimension has equal weight; correlated scoring/shooting features can overweight that aspect. Constant dimensions are omitted. No outcome validation or talent-equivalence claim is made. ${p.minutes<500?'The selected player has fewer than 500 minutes; their profile may be unstable.':''}</p></details></section>`;
}

function wirePlayers(){$('#similarRole').onchange=e=>{state.similarRole=e.target.checked;render()};document.querySelectorAll('[data-similar]').forEach(button=>button.onclick=()=>{state.compare=button.dataset.similar;render();document.querySelector('.player-selects').scrollIntoView({block:'start'});$('#compare').focus({preventScroll:true})});$('#season').onchange=e=>{state.season=e.target.value;render()};['player','compare'].forEach(id=>$('#'+id).onchange=e=>{state[id]=e.target.value;render()});$('#search').oninput=e=>{const query=e.target.value.trim().toLowerCase(),matches=D.players.filter(p=>p.season===state.season&&p.minutes>=100&&p.player_name.toLowerCase().includes(query));$('#searchCount').textContent=query?matches.length+' matches · choose a player or press Enter':D.players.filter(p=>p.season===state.season&&p.minutes>=100).length+' players with ≥100 minutes';$('#searchResults').innerHTML=query?matches.slice(0,8).map(p=>`<button class="chip" data-search-player="${esc(p.player_name)}">${esc(p.player_name)} · ${esc(p.team)}</button>`).join('')||( '<p class="muted small">No players match that name in this season.</p>'):'';document.querySelectorAll('[data-search-player]').forEach(button=>button.onclick=()=>{state.player=button.dataset.searchPlayer;render();$('#player').focus({preventScroll:true})})};$('#search').onkeydown=e=>{if(e.key==='Enter'){const first=document.querySelector('[data-search-player]');if(first){state.player=first.dataset.searchPlayer;render();$('#player').focus({preventScroll:true})}}}}

function lineups(){const all=S.lineups.filter(l=>l.team===state.team).map(l=>({...l,shrunk:(l.poss*l.net+state.priorStrength*l.prior)/(l.poss+state.priorStrength)})),roster=new Map();all.forEach(l=>l.ids.forEach((id,i)=>roster.set(id,l.names[i])));const exact=state.selected.length===5?all.find(l=>l.ids.every(id=>state.selected.includes(id))):null,rows=all.filter(l=>l.poss>=state.minPoss).sort((a,b)=>b.shrunk-a.shrunk);return `${head('FIVE ON THE FLOOR','Who plays well together?','Investigate observed combinations with sample-aware ratings. Build a five-player group to check whether it exists in the data.')}<div class="filters"><label>Team<select id="lineupTeam">${teamOptions(state.team)}</select></label><label>Minimum possessions<select id="minPoss">${[0,50,100,250,500].map(n=>`<option value="${n}" ${n===state.minPoss?'selected':''}>${n} possessions</option>`).join('')}</select></label><label>Shrinkage prior<select id="priorStrength">${[50,200,500].map(n=>`<option value="${n}" ${n===state.priorStrength?'selected':''}>${n} possessions</option>`).join('')}</select></label><span class="filter-spacer"></span><span class="tiny muted">${all.length} units available · coverage may be capped</span></div><div class="grid2 equal">${panel('Build a lineup',`<div class="row between"><span class="small muted">Select five players · ${state.selected.length}/5</span><button class="btn" id="clearLineup">Clear</button></div><div class="lineup-options">${[...roster].sort((a,b)=>a[1].localeCompare(b[1])).map(([id,name])=>`<button class="chip ${state.selected.includes(id)?'selected':''}" data-player-id="${id}" aria-pressed="${state.selected.includes(id)}">${esc(name)}</button>`).join('')}</div><p class="footnote">Roster choices come from observed 2024–25 lineup units, including players who changed teams during the season.</p>`)}${panel('Observed evidence',exact?`<div class="grid3">${kpi('Raw net',signed(exact.net),'Points / 100 poss')}${kpi('Shrunk net',signed(exact.shrunk),state.priorStrength+'-possession prior','green')}${kpi('Possessions',count(exact.poss),'Observed sample')}</div><p class="footnote">Offense ${fmt(exact.off)} · Defense ${fmt(exact.defense)} · Rebound share ${pct(exact.drb)} defensive. Prior = possession-weighted mean of available team lineups (${signed(exact.prior)}).</p><h3 class="section">Sensitivity to the prior</h3><div class="table-wrap"><table><thead><tr><th>PRIOR</th><th>SHRUNK NET</th><th>RANK WITHIN FILTER</th></tr></thead><tbody>${[50,200,500].map(k=>{const value=(exact.poss*exact.net+k*exact.prior)/(exact.poss+k),rank=1+all.filter(l=>l.poss>=state.minPoss&&(l.poss*l.net+k*l.prior)/(l.poss+k)>value).length;return `<tr><td>${k} possessions</td><td>${signed(value)}</td><td>${exact.poss>=state.minPoss?rank:'Below threshold'}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty">${state.selected.length===5?'This combination is absent from the export. Its performance is unknown.':'Choose five players to inspect their observed performance.'}</div>`)}</div>${lineupStudyLibrary(S.lineups,esc)}${lineupComparisonPanel(all,state,esc)}${rotationFinderPanel(all,state,esc)}<div class="note warning">Shrinkage reduces extreme small-sample values; it does not adjust for opponent strength, garbage time, or who shares the floor. The chosen prior is a sensitivity assumption, not a fitted optimal value. Compare 50, 200 and 500 to see whether the ranking is stable. These are scouting candidates, not proven optimal rotations.</div>`}
function wireLineups(){wireRotationFinder(S.lineups.filter(l=>l.team===state.team),state,render);wireLineupStudyLibrary(S.lineups,state,render);wireLineupComparison(S.lineups.filter(l=>l.team===state.team),state,render);$('#lineupTeam').onchange=e=>{state.team=e.target.value;state.selected=[];state.rotationInclude='';state.rotationExclude='';render()};$('#minPoss').onchange=e=>{state.minPoss=+e.target.value;render()};$('#priorStrength').onchange=e=>{state.priorStrength=+e.target.value;render()};$('#clearLineup').onclick=()=>{state.selected=[];render()};document.querySelectorAll('[data-player-id]').forEach(b=>b.onclick=()=>{const id=+b.dataset.playerId;if(state.selected.includes(id))state.selected=state.selected.filter(x=>x!==id);else if(state.selected.length<5)state.selected.push(id);render()});document.querySelectorAll('[data-lineup]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.lineup.split(',').map(Number);render();window.scrollTo({top:0,behavior:'smooth'})})}
async function shots(id){const t=state.shotTeam;let data=shotCache[t];if(!data){const r=await fetch(`shots/${t}.json`,{cache:'no-cache'});if(!r.ok)throw Error('Shot dataset unavailable');data=await r.json();shotCache[t]=data}if(id!==renderID)return;const rows=data.shots.filter(r=>(state.shotPlayer==='all'||r[0]===+state.shotPlayer)&&(state.zone==='all'||r[5]===+state.zone)&&(state.shotType==='all'||r[4]===+state.shotType)),made=rows.reduce((s,r)=>s+r[3],0),points=rows.reduce((s,r)=>s+r[3]*r[4],0),expected=rows.reduce((s,r)=>s+S.league.find(z=>z.zone===r[5]).pps,0),modelExpected=rows.reduce((s,r)=>s+r[6]*r[4],0),ci=wilson(made,rows.length),evidence=shotEvidence(rows,S.league.filter(z=>(state.zone==='all'||z.zone===+state.zone)&&(state.shotType==='all'||(z.zone<3?2:3)===+state.shotType)));$('#main').innerHTML=`${head('SHOT CHARTS','Where the points come from.','Explore real shot locations, geometric zones, and the difference between shot selection and observed conversion.')}<div class="filters"><label>Team<select id="shotTeam">${teamOptions(t)}</select></label><label>Player<select id="shotPlayer"><option value="all">All players</option>${data.players.sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${p.id}" ${String(p.id)===state.shotPlayer?'selected':''}>${esc(p.name)} · #${p.id}</option>`).join('')}</select></label><label>Zone<select id="shotZone"><option value="all">All zones</option>${S.zones.map((z,i)=>`<option value="${i}" ${String(i)===state.zone?'selected':''}>${z}</option>`).join('')}</select></label><label>Shot value<select id="shotType"><option value="all">All shots</option><option value="2" ${state.shotType==='2'?'selected':''}>Two-pointers</option><option value="3" ${state.shotType==='3'?'selected':''}>Three-pointers</option></select></label></div><div class="grid4">${kpi('Attempts',count(rows.length),'Full filtered sample')}${kpi('Field goal %',rows.length?pct(made/rows.length):'—','95% Wilson: '+pct(ci[0],0)+'–'+pct(ci[1],0),'green')}${kpi('Points / shot',rows.length?fmt(points/rows.length,3):'—','Observed · excludes free throws')}${kpi('Modeled expected PPS',rows.length?fmt(modelExpected/rows.length,3):'—','Trained on prior seasons · conditional on shot')}</div><div class="shot-layout section">${panel('The shot map',`<div class="court-wrap">${court()}<canvas id="shotCanvas" width="1000" height="940" role="img" aria-label="${count(rows.length)} filtered shots: ${count(made)} made and ${count(rows.length-made)} missed. Exact aggregates are in the adjacent table."></canvas></div><div class="court-legend"><span><i class="legend-dot" style="background:#a64327"></i>Made</span><span><i class="legend-dot" style="background:#285e78"></i>Missed</span></div><p class="footnote">All filtered shots plotted; overlapping points can hide density. Attempts beyond half court are omitted from this map but retained in statistics.</p>`,'ACTUAL COORDINATES')}${panel('Zone efficiency',`<div class="table-wrap"><table><thead><tr><th>ZONE</th><th>FGA</th><th>FG%</th><th>PPS</th></tr></thead><tbody>${S.zones.map((z,i)=>{const r=rows.filter(s=>s[5]===i),m=r.reduce((s,x)=>s+x[3],0);return `<tr><td>${z}</td><td>${r.length}</td><td>${r.length?pct(m/r.length):'—'}</td><td>${r.length?fmt(r.reduce((s,x)=>s+x[3]*x[4],0)/r.length,2):'—'}</td></tr>`}).join('')}</tbody></table></div><div class="section"><h3>Shot selection profile</h3>${S.zones.map((z,i)=>{const n=rows.filter(s=>s[5]===i).length;return bar(z,rows.length?n/rows.length*100:0,rows.length?pct(n/rows.length):'—')}).join('')}</div><p class="footnote">Modeled expected points use location, shot value, period and period clock. No defender tracking or shot-clock data is included. The observed-minus-expected gap is not an isolated measure of shooter skill. Descriptive zone-reference PPS: ${rows.length?fmt(expected/rows.length,3):'—'}. Player IDs are preserved from the source.</p>`)}</div>${renderShotEvidence(evidence,S.zones)}`;
 if($('#exportShotEvidence'))$('#exportShotEvidence').onclick=()=>{const payload={schemaVersion:1,snapshot:'2024–25 regular season',team:state.shotTeam,playerId:state.shotPlayer,zone:state.zone,shotValue:state.shotType,zoneNames:S.zones,units:'points per field-goal attempt; multiply contributions by 100 for displayed units',reference:'same-season league, restricted to selected zones and values; includes selected sample',model:'prior-season location/context model; held-out 2024–25 shots',limitation:'Descriptive decomposition; residuals do not isolate skill or causal impact',...evidence};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='CourtVision-'+state.shotTeam+'-shot-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 const c=$('#shotCanvas').getContext('2d');c.scale(2,2);for(const r of rows){const x=250+r[1],y=417.5-r[2];if(x<0||x>500||y<0||y>470)continue;c.fillStyle=r[3]?'rgba(166,67,39,.52)':'rgba(40,94,120,.26)';c.beginPath();c.arc(x,y,1.8,0,Math.PI*2);c.fill()}
 $('#shotTeam').onchange=e=>{state.shotTeam=e.target.value;state.shotPlayer='all';render()};[['shotPlayer','shotPlayer'],['shotZone','zone'],['shotType','shotType']].forEach(([id,k])=>$('#'+id).onchange=e=>{state[k]=e.target.value;render()});}
function strategy(){if(state.home===state.away)return head('SCOUTING NOTES','What to watch for.','Choose two different teams.')+matchupFilters()+'<div class="empty">Choose different teams.</div>';const m=match(),a=m.a.profile,b=m.b.profile;const cards=[{n:'01',title:'Shooting efficiency alignment',ob:`${state.home} posted ${pct(a.efg)} effective FG% in its last 10 games. ${state.away} allowed ${pct(b.allowed_efg)} over its last 10.`,rec:a.efg>.54&&b.allowed_efg>.54?'Review film for ways to preserve efficient attempts against this opponent. The offensive strength and defensive allowance align above the declared 54% reference.':'The aggregate shooting screen does not show a clear above-reference alignment. Inspect zone-level patterns before proposing a shooting adjustment.',impact:'Potential outcome: better shot selection. No causal points-gained estimate is available.',limit:'Ten-game windows are noisy; opponent quality and player availability are uncontrolled.',chart:bar(state.home+' offensive eFG',a.efg*100,pct(a.efg))+bar(state.away+' allowed eFG',b.allowed_efg*100,pct(b.allowed_efg),'var(--cyan)')},{n:'02',title:'Second-chance opportunity',ob:`${state.home} recovered ${pct(a.orb)} of available offensive rebounds. ${state.away} allowed opponents ${pct(b.allowed_orb)}.`,rec:a.orb>.27&&b.allowed_orb>.27?'Investigate whether selective offensive crashing can exploit the observed rebounding alignment while preserving transition defense.':'Evaluate offensive rebounding against transition-defense costs. These aggregates alone do not establish a matchup edge.',impact:'Potential outcome: additional possessions. Impact requires a controlled tactical test.',limit:'Available rebound shares are box-score estimates averaged by game, not player-tracking opportunities.',chart:bar(state.home+' offensive rebound share',a.orb*100,pct(a.orb))+bar(state.away+' allowed share',b.allowed_orb*100,pct(b.allowed_orb),'var(--cyan)')},{n:'03',title:'Ball security versus pressure',ob:`${state.home} turnover rate: ${pct(a.tov)}. ${state.away} opponent turnover rate: ${pct(b.forced_tov)}.`,rec:b.forced_tov>.13?'Review pressure-release options and ball-handler combinations. The opponent generated turnovers above the declared 13% reference.':'Inspect whether secure possession patterns carry into this matchup. Low aggregate turnover creation is not proof of weak on-ball defense.',impact:'Potential outcome: fewer empty possessions. No guaranteed improvement is implied.',limit:'These rates do not identify trap coverage, live-ball turnovers, or individual defensive pressure.',chart:bar(state.home+' turnover rate',a.tov*300,pct(a.tov))+bar(state.away+' forced rate',b.forced_tov*300,pct(b.forced_tov),'var(--cyan)')}];const ev=D.evaluation.results;return `${head('SCOUTING NOTES','What to watch for.','A few matchup patterns to investigate, with the numbers behind each one.')}${matchupFilters()}${analysisLinks()}<div class="grid3">${kpi(state.home+' → '+state.away+' vulnerability',fmt(vulnerability(a,b),2),'Experimental alignment index','green')}${kpi(state.away+' → '+state.home+' vulnerability',fmt(vulnerability(b,a),2),'Fixed reference thresholds')}${kpi('MVI improvement · 2024–25',fmt(ev.core.log_loss-ev.experimental_mvi.log_loss,4),'Held-out ablation · very small')}</div><div class="note warning">The Matchup Vulnerability Index is exploratory. Its held-out gain has a 95% paired week-bootstrap interval of ${fmt(D.evaluation.mvi_ablation.interval_95[0],5)} to ${fmt(D.evaluation.mvi_ablation.interval_95[1],5)}, spanning zero. On the fresh 2025–26 audit, MVI is slightly worse than the core model (log loss ${fmt(D.evaluation.audit.results.experimental_mvi.log_loss,4)} vs ${fmt(D.evaluation.audit.results.core.log_loss,4)}). Use these cards to prioritize film review, not as proven coaching interventions.</div><div class="section">${cards.map(c=>`<details class="strategy-card"><summary><span class="flow-number">${c.n}</span><div><h3>${c.title}</h3><span class="tiny muted">${state.home} offense × ${state.away} defense · 10 games each</span></div></summary><p><strong>Observation:</strong> ${c.ob}</p>${c.chart}<div class="evidence-grid"><div><h4>CONSIDER TESTING</h4><p>${c.rec}</p></div><div><h4>EXPECTED IMPACT</h4><p>${c.impact}</p></div><div><h4>CONFIDENCE & LIMITS</h4><p>${c.limit}</p></div></div></details>`).join('')}</div>`}
function calibration(r,unit='games'){return `<svg class="calibration" viewBox="0 0 330 240" role="img" aria-label="Calibration plot: predicted versus observed home win rates. Perfect calibration is the diagonal."><g stroke="#c9bbaa">${[0,.25,.5,.75,1].map(v=>`<line x1="45" x2="300" y1="${205-v*180}" y2="${205-v*180}"/><text x="35" y="${209-v*180}" fill="#635b54" font-size="9" stroke="none" text-anchor="end">${v}</text>`).join('')}</g><path d="M45 205L300 25" stroke="#635b54" stroke-dasharray="5 5"/>${r.calibration.map(b=>`<circle cx="${45+b.predicted*255}" cy="${205-b.observed*180}" r="${Math.max(3,18*Math.sqrt(b.n/Math.max(...r.calibration.map(x=>x.n))))}" fill="#a64327" opacity=".8"><title>${b.n} ${unit} · predicted ${pct(b.predicted)} · observed ${pct(b.observed)}</title></circle>`).join('')}<text x="170" y="235" fill="#635b54" font-size="10" text-anchor="middle">Predicted home win probability</text></svg>`}
function methodology(){const ev=D.evaluation,r=ev.results[ev.selected];return `${head('ABOUT THE DATA','The numbers behind the notebook.','The data, assumptions, validation results, and limitations behind every part of this workspace.','REPRODUCIBLE · V0.1')}<div class="grid4">${kpi('Training games',count(ev.split_counts.train),'2022–23')}${kpi('Validation games',count(ev.split_counts.validation),'2023–24 · model selection')}${kpi('Test games',count(ev.split_counts.test),'2024–25 · held out','green')}${kpi('Selected test accuracy',pct(r.accuracy),'Compare probability metrics below')}</div><div class="grid2 section">${panel('Chronological model comparison',`<div class="table-wrap"><table><thead><tr><th>MODEL</th><th>LOG LOSS ↓</th><th>BRIER ↓</th><th>ACCURACY</th></tr></thead><tbody>${Object.entries(ev.results).map(([name,v])=>`<tr><td>${name===ev.selected?'● ':''}${{strength:'Net-rating only',core:'Core features',experimental_mvi:'Core + exploratory MVI',elo:'Elo-informed logistic',home_base_rate:'Home base rate'}[name]}</td><td>${fmt(v.log_loss,4)}</td><td>${fmt(v.brier,4)}</td><td>${pct(v.accuracy)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">Selected by lowest validation-season log loss, then refit on training + validation. Test outcomes were not used for selection. One season of testing does not establish broad generalization.</p>`)}${panel('Held-out calibration',calibration(r)+'<p class="footnote">Observed win rate versus predicted probability, in ten fixed bins. Point sizes indicate relative sample counts. The diagonal represents perfect calibration; no post-hoc calibration was fitted.</p>')}</div><div class="section">${panel('Fresh-season audit · 2025–26',`<div class="table-wrap"><table><thead><tr><th>MODEL</th><th>LOG LOSS ↓</th><th>BRIER ↓</th><th>ACCURACY</th></tr></thead><tbody>${Object.entries(ev.audit.results).map(([n,v])=>`<tr><td>${n===ev.selected?'● ':''}${{strength:'Net-rating only',core:'Core features',experimental_mvi:'Core + exploratory MVI',elo:'Elo-informed logistic',home_base_rate:'Home base rate'}[n]}</td><td>${fmt(v.log_loss,4)}</td><td>${fmt(v.brier,4)}</td><td>${pct(v.accuracy)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">${ev.audit.n} eligible games. Experiment 02 was specified before evaluating this season. It was never used for fitting or selection. The earlier 2024–25 results had already been inspected; this audit adds a separate check. The workspace remains a 2024–25 historical snapshot.</p>`)}</div><div class="grid2 section">${panel('Shot-model evaluation',`<div class="table-wrap"><table><thead><tr><th>MODEL</th><th>LOG LOSS ↓</th><th>BRIER ↓</th><th>ACCURACY</th></tr></thead><tbody>${Object.entries(S.shot_model.results).map(([n,v])=>`<tr><td>${{location_context:'Location + context',shot_value_baseline:'Shot-value baseline',overall_baseline:'Overall make rate'}[n]}</td><td>${fmt(v.log_loss,4)}</td><td>${fmt(v.brier,4)}</td><td>${pct(v.accuracy)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">2024–25 held-out shots. Complexity selected using 2023–24; fitted on 2022–23 and 2023–24. Conditional conversion estimates, not forecasts of shot choice.</p>`)}${panel('Shot-model calibration',calibration(S.shot_model.results.location_context,'shots').replace('Predicted home win probability','Predicted shot make probability').replace('predicted versus observed home win rates','predicted versus observed shot make rates')+'<p class="footnote">Ten fixed bins. Period time remaining is not shot-clock time; defender pressure is unavailable.</p>')}</div><div class="grid2 equal section"><section class="panel method-text"><h2>Data & provenance</h2><h3>Team and player statistics</h3><p>Three displayed regular seasons plus a separate 2025–26 team-game audit from <a href="https://boxscorelab.com/downloads/" target="_blank" rel="noreferrer">BoxScore Lab</a>, sourced from NBA Stats and published under <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>. Seven CSV snapshots, SHA-256 hashes, and ingestion scripts are included. ${count(D.players.length)} player-season rows; ${D.teams.length} team-season profiles.</p><h3>Shots and lineups</h3><p><a href="https://github.com/sportsdataverse/hoopR-nba-stats-data">SportsDataverse / hoopR</a>, sourced from NBA Stats. Producer's <a href="${S.license_url}">CC BY 4.0 data license</a>. We filter 2025 ending-year releases to regular season, then filter lineups to advanced/totals to avoid duplicate measurement panels.</p><h3>What changed</h3><p>We compute possession estimates, rolling pregame features, player per-36 rates, geometric shot zones, and lineup shrinkage. Source bytes remain cached with checksums. Seasons and historical affiliations are always visible.</p><h3>Shot-outcome model</h3><p>A histogram gradient-boosted classifier estimates make probability conditional on an attempted shot. Inputs: x/y location, distance, shot value, period and period seconds remaining. Train 2022–23 (${count(S.shot_model.counts[0])} shots); select complexity on 2023–24 (${count(S.shot_model.counts[1])}); refit on both; test on 2024–25 (${count(S.shot_model.counts[2])}). Test log loss: <strong>${fmt(S.shot_model.results.location_context.log_loss,4)}</strong> vs <strong>${fmt(S.shot_model.results.shot_value_baseline.log_loss,4)}</strong> for a training-derived two/three-point baseline. Brier: ${fmt(S.shot_model.results.location_context.brier,4)}. No defender-pressure or causal shot-selection claim is supported.</p><h3>Snapshot boundaries</h3><p>This is a historical 2024–25 research edition, not live scouting. Player season aggregates may span traded-team stints. Shot IDs are preserved independently; surname matching is never used to join players. Some older positions are missing.</p></section><section class="panel method-text"><h2>Prediction model</h2><h3>Target and features</h3><p>Predict whether the home team wins a regular-season game. Candidates use either the pregame Elo rating gap or differences in previous-ten-game box-score features. The selected Elo logistic model uses one rating-gap feature; its intercept accounts for home advantage. Rest is not included in that selected model.</p><h3>Leakage prevention</h3><p>Every rolling feature is shifted one game before its 10-game window. Both teams need 10 prior games in the same season. Scaling is fitted only on training rows. Regularization C is selected from 0.01, 0.1, 1, 10 on 2023–24. The Elo candidate uses pregame ratings updated only after outcomes (K=20, home offset 75, scale 400), reset to 1500 each season. Neutral-site games without a home side are excluded from predictions. ${ev.excluded_games} games are excluded across all four team-game seasons.</p><h3>Model and uncertainty</h3><p>L2-regularized logistic regression. Sixty seeded training-week bootstrap refits produce a 10th–90th percentile probability range. This measures model instability, not all uncertainty. The selected model uses opponent-adjusted sequential Elo strength. Box-score comparisons remain unadjusted descriptive rates.</p><h3>Portable inference</h3><p>This dashboard calculates from exported coefficients in your browser. The local FastAPI service exposes the same model at <code>POST /api/matchup</code>. No hardcoded matchup probabilities are used.</p></section></div><div class="grid2 equal section"><section class="panel method-text"><h2>Analytical definitions</h2><p><strong>Possessions:</strong> average of each team's FGA + 0.44 × FTA − OREB + TOV. Not adjusted for overtime duration, so possessions/game is not exact pace per 48 minutes.</p><p><strong>eFG:</strong> (FGM + 0.5 × 3PM) / FGA.<br><strong>True shooting:</strong> PTS / [2 × (FGA + 0.44 × FTA)].<br><strong>Turnover rate:</strong> TOV / (FGA + 0.44 × FTA + TOV).<br><strong>Offensive rebound share:</strong> OREB / (OREB + opponent DREB).</p><p><strong>Lineup shrinkage:</strong> (poss × raw net + 200 × team prior) / (poss + 200). The prior is the possession-weighted mean of available team units. Coverage is incomplete; this is not a causal lineup-impact model.</p><p><strong>Shot zones:</strong> at rim ≤4 ft; paint within ±8 ft and ≤13.75 ft forward; other twos mid-range; corner threes at |x| ≥22 ft and y ≤9.25 ft; other threes above break. These are approximate geometric categories, not official NBA zone labels.</p></section><section class="panel method-text"><h2>Experimental vulnerability index</h2><p>For offense A against defense B, average three nonnegative products:</p><p><code>[(A.eFG − .54)/.05]+ × [(B.allowed eFG − .54)/.05]+</code></p><p><code>[(A.ORB − .27)/.05]+ × [(B.allowed ORB − .27)/.05]+</code></p><p><code>[(.13 − A.TOV)/.03]+ × [(.13 − B.forced TOV)/.03]+</code></p><p>Here [x]+ = max(0, x). Fixed thresholds, equal weights, and scales are declared assumptions. The model uses A→B minus B→A. All inputs use prior-game windows.</p><p>Held-out log-loss improvement over the core model: <strong>${fmt(ev.results.core.log_loss-ev.results.experimental_mvi.log_loss,5)}</strong>. The paired week-bootstrap 95% interval for log-loss improvement is ${fmt(ev.mvi_ablation.interval_95[0],5)} to ${fmt(ev.mvi_ablation.interval_95[1],5)}, spanning zero. On the fresh 2025–26 audit, MVI is slightly worse than core (${fmt(ev.audit.results.experimental_mvi.log_loss,4)} vs ${fmt(ev.audit.results.core.log_loss,4)} log loss). The index is exploratory and should not be promoted as validated strategic advantage.</p></section></div><div class="note">Original software is MIT licensed. Third-party datasets retain their own CC BY 4.0 licenses. This project is independent of the NBA, its teams, BoxScore Lab, and SportsDataverse.</div><div class="row section"><a class="btn" href="evaluation.json" download>Download evaluation JSON ↓</a><a class="btn" href="provenance.json" download>Download provenance ↓</a><a class="btn" href="shot_evaluation.json" download>Download shot evaluation ↓</a></div>`}
async function render(){const focused=document.activeElement?.id;const id=++renderID;route=location.hash.slice(1)||'overview';if(!PAGES.some(p=>p[0]===route))route='overview';$('#nav').innerHTML=PAGES.map(([key,icon,label])=>`<a href="#${key}" class="${key===route?'active':''}" ${key===route?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('');$('#crumb').textContent=PAGES.find(p=>p[0]===route)[2];document.title=PAGES.find(p=>p[0]===route)[2]+' · Courtvision';try{if(route==='shots'){$('#main').innerHTML='<div class="loading"><span class="spinner"></span>Loading shot locations…</div>';await shots(id);if(id===renderID&&focused)document.getElementById(focused)?.focus({preventScroll:true});return}$('#main').innerHTML=(route==='series'?renderSeries(D,state,NAMES):({overview,matchup,players,lineups,strategy,methodology}[route])());if(['matchup','strategy'].includes(route)){wireMatchup();wireAnalysisLinks();}if(route==='overview')wireOverview();if(route==='players')wirePlayers();if(route==='series')wireSeries(D,state,render);if(route==='lineups')wireLineups();if(focused)document.getElementById(focused)?.focus({preventScroll:true})}catch(e){if(id!==renderID)return;$('#main').innerHTML=`<div class="empty"><h2>We couldn’t load this analysis.</h2><p>${esc(e.message)}</p><button class="btn" id="retry">Try again</button></div>`;$('#retry').onclick=render;console.error(e)}}
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'})});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
try{const responses=await Promise.all([fetch('data.json',{cache:'no-cache'}),fetch('spatial.json',{cache:'no-cache'})]);if(responses.some(r=>!r.ok))throw Error('Data files unavailable. Serve this directory over HTTP.');[D,S]=await Promise.all(responses.map(r=>r.json()));await render()}catch(e){$('#main').innerHTML=`<div class="empty"><h1>Data unavailable</h1><p>${esc(e.message)}</p><button class="btn" onclick="location.reload()">Retry loading</button></div>`}
